/**
 * Permanent pack ownership from explicit save fields.
 * Field names/types: data/player-stats PLAYER_DATA_FIELDS_BY_DOMAIN; also present
 * as boolean properties in the official v1253 External Tools Export.
 * No purchase-history, coin-total or multiplier inference is performed.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    readPurchasesFromSaveRoot
 * depends    src/save/purchases/types
 * used by    src/calculators/specs.generated, src/save/purchases/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { PurchasesSaveExtract } from './types'

export function readPurchasesFromSaveRoot(root: Record<string, unknown> | null): PurchasesSaveExtract | null {
  if (!root) return null
  const unreadableKeys: string[] = []
  const flag = (key: string): boolean | null => {
    if (typeof root[key] === 'boolean') return root[key] as boolean
    unreadableKeys.push(key)
    return null
  }
  return {
    hasStarterPack: flag('starterPackUnlockedBool'),
    hasEpicPack: flag('epicPackUnlockedBool'),
    hasDisableAds: flag('disableAdsUnlockedBool'),
    unreadableKeys,
  }
}
